contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(amount == 10);
        require(address(this).balance >= amount);
        c.play{value: amount}();
        uint potBefore = 0;
        uint balanceBefore = 0;
        uint potAfter = c.pot();
        uint balanceAfter = address(c).balance;
        // pot before was potAfter - 10 (loss) or 0 (win); express conservation as:
        // balanceAfter + potBefore == balanceBefore + potAfter
        // with potBefore derived: if potAfter == 0, potBefore == 0, so require balanceAfter == balanceBefore is implied by the sum form with potBefore = 0.
        if (potAfter == 0) {
            // win (or pot unchanged): balance must be unchanged too
            assert(balanceAfter == balanceBefore);
        } else {
            // loss: both grew by exactly 10
            assert(balanceAfter == potAfter + (balanceBefore - potBefore));
        }
    }

    receive() external payable {}
}

